//! Compile-time PDF.js assets for the LAN Web Reader.
//!
//! The table is generated by `build.rs` from the same `pdfjs-dist` package the
//! desktop bundle uses. Only the legacy module build, its worker, the CMaps and
//! the standard 14 font data are embedded; WASM decoders and the `quickjs`
//! document-script sandbox are deliberately absent so the reader CSP stays
//! `script-src 'self'` without `wasm-unsafe-eval`.

include!(concat!(env!("OUT_DIR"), "/pdf_assets.rs"));

/// Exact-name lookup. Unknown or traversal-shaped paths return `None`; callers
/// answer the same static 404 as every other unknown reader asset.
pub(crate) fn lookup(name: &str) -> Option<(&'static [u8], &'static str)> {
    PDF_ASSETS
        .iter()
        .find(|(asset, _, _)| *asset == name)
        .map(|(_, bytes, mime)| (*bytes, *mime))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn only_the_approved_pdfjs_assets_are_embedded() {
        assert!(lookup("pdf.min.mjs").is_some());
        assert!(lookup("pdf.worker.min.mjs").is_some());
        assert!(lookup("cmaps/UniGB-UCS2-H.bcmap").is_some());
        assert!(lookup("standard_fonts/LiberationSans-Regular.ttf").is_some());
        // WASM decoders and the document-script sandbox must never ship here.
        assert!(lookup("wasm/openjpeg.wasm").is_none());
        assert!(lookup("quickjs-eval.mjs").is_none());
        assert!(lookup("../Cargo.toml").is_none());
    }
}
